package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class FormalScoreBindingSchemaTest {
 final PermissionSchema json=new PermissionSchema();final FormalAgentPublicationSchema general=new FormalAgentPublicationSchema(json);final FormalEvaluationScoreBindingSchema schema=new FormalEvaluationScoreBindingSchema(general);
 FormalScoreBindingSchemaTest()throws Exception{}
 JsonNode body(){var n=json.object().put("schema_version","1.0.0");String id=PublicationLedgerFixture.id(1),hash="a".repeat(64);n.set("evaluation",json.tree(new PermissionProtocol.Basis(id,hash)));n.set("statistics_policy",json.tree(new PermissionProtocol.Basis(PublicationLedgerFixture.id(2),hash)));n.set("binding",json.tree(new ExpertQualificationProtocol.BindScore("1.0.0",id,PublicationLedgerFixture.id(3),hash,hash,new PermissionProtocol.Basis(PublicationLedgerFixture.id(4),hash),"PTR expert review","Actual fixed score binding")));return n;}
 @Test void exactClosedOuterRequestValidatesWithoutGrantingQualification()throws Exception{assertEquals(general.canonical(body()),general.canonical(schema.request(general.canonical(body()).getBytes(java.nio.charset.StandardCharsets.UTF_8))));}
 @Test void mismatchedDefinitionRejected()throws Exception{var n=body();((com.fasterxml.jackson.databind.node.ObjectNode)n.path("binding")).put("definition_sha256","b".repeat(64));assertThrows(SchemaRejection.class,()->schema.validate(n));}
 @Test void extraApprovalBooleanRejected()throws Exception{var n=(com.fasterxml.jackson.databind.node.ObjectNode)body();n.put("approved",true);assertThrows(SchemaRejection.class,()->schema.validate(n));}
 @Test void duplicateKeyRejectedBeforeCanonicalization()throws Exception{String text=general.canonical(body());text=text.replace("\"schema_version\":\"1.0.0\"","\"schema_version\":\"1.0.0\",\"schema_version\":\"1.0.0\"");String exact=text;assertThrows(java.io.IOException.class,()->schema.request(exact.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 @Test void invalidUtf8CannotBeSilentlyReplaced()throws Exception{assertThrows(java.io.IOException.class,()->schema.request(new byte[]{123,34,120,34,58,34,(byte)0xc3,34,125}));}
 @Test void recoveryHasOriginalKeyAndExactInnerRequest()throws Exception{var n=json.object().put("schema_version","1.0.0").put("original_key","original-formal-key-001");n.set("request",body());assertEquals(general.canonical(n),general.canonical(schema.recovery(general.canonical(n).getBytes(java.nio.charset.StandardCharsets.UTF_8))));n.put("new_key","forbidden");assertThrows(SchemaRejection.class,()->schema.recovery(general.canonical(n).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
}
